ALTER TABLE public.production_modules ADD COLUMN blocks jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.production_enrollments ADD COLUMN dj_enabled boolean NOT NULL DEFAULT false;
UPDATE public.production_enrollments SET dj_enabled=true;
DROP POLICY production_enrollment_staff ON public.production_enrollments;
CREATE POLICY production_enrollment_admin ON public.production_enrollments FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY production_enrollment_update ON public.production_enrollments FOR UPDATE TO authenticated USING(instructor_id=auth.uid() AND public.is_production_instructor(auth.uid())) WITH CHECK(instructor_id=auth.uid() AND public.is_production_instructor(auth.uid()));
CREATE FUNCTION public.protect_production_enrollment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.is_admin() AND (NEW.student_id IS DISTINCT FROM OLD.student_id OR NEW.instructor_id IS DISTINCT FROM OLD.instructor_id OR NEW.dj_enabled IS DISTINCT FROM OLD.dj_enabled OR NEW.active IS DISTINCT FROM OLD.active) THEN RAISE EXCEPTION 'Only admins can change program access'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_production_enrollment BEFORE UPDATE ON public.production_enrollments FOR EACH ROW EXECUTE FUNCTION public.protect_production_enrollment();
CREATE FUNCTION public.production_staff_access(_enrollment uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.is_admin() OR EXISTS(SELECT 1 FROM public.production_enrollments WHERE id=_enrollment AND instructor_id=auth.uid() AND public.is_production_instructor(auth.uid())) $$;
REVOKE ALL ON FUNCTION public.production_staff_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.production_staff_access(uuid) TO authenticated,service_role;
CREATE TABLE public.production_intakes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL UNIQUE REFERENCES public.production_enrollments(id) ON DELETE CASCADE, daw text NOT NULL DEFAULT '', hardware text NOT NULL DEFAULT '', genres text NOT NULL DEFAULT '', goals text NOT NULL DEFAULT '', experience text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.production_intakes TO authenticated; GRANT ALL ON public.production_intakes TO service_role;
ALTER TABLE public.production_intakes ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_read ON public.production_intakes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id));
CREATE POLICY intake_staff ON public.production_intakes FOR ALL TO authenticated USING(public.production_staff_access(enrollment_id)) WITH CHECK(public.production_staff_access(enrollment_id));
CREATE TRIGGER intake_updated BEFORE UPDATE ON public.production_intakes FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES public.production_enrollments(id) ON DELETE CASCADE, module_id uuid NOT NULL REFERENCES public.production_modules(id) ON DELETE CASCADE, block_id text NOT NULL, student_note text NOT NULL DEFAULT '', media_url text NOT NULL DEFAULT '', storage_path text, status text NOT NULL DEFAULT 'pending_review' CHECK(status IN('pending_review','complete','changes_requested')), feedback text NOT NULL DEFAULT '', reviewed_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.production_submissions TO authenticated; GRANT ALL ON public.production_submissions TO service_role;
ALTER TABLE public.production_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submission_read ON public.production_submissions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id));
CREATE POLICY submission_student ON public.production_submissions FOR INSERT TO authenticated WITH CHECK(status='pending_review' AND feedback='' AND reviewed_by IS NULL AND EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.student_id=auth.uid() AND e.active) AND EXISTS(SELECT 1 FROM public.production_modules m WHERE m.id=module_id AND NOT m.is_draft AND (EXISTS(SELECT 1 FROM jsonb_array_elements(m.blocks) b WHERE b->>'id'=block_id AND b->>'type'='homework') OR (block_id='legacy-homework' AND m.homework_prompt<>''))) AND (storage_path IS NULL OR split_part(storage_path,'/',2)=auth.uid()::text));
CREATE POLICY submission_staff ON public.production_submissions FOR UPDATE TO authenticated USING(public.production_staff_access(enrollment_id)) WITH CHECK(public.production_staff_access(enrollment_id));
CREATE TRIGGER submission_updated BEFORE UPDATE ON public.production_submissions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_catchups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES public.production_enrollments(id) ON DELETE CASCADE, module_id uuid NOT NULL REFERENCES public.production_modules(id) ON DELETE CASCADE, class_date date NOT NULL, note text NOT NULL DEFAULT '', sent_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,class_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.production_catchups TO authenticated; GRANT ALL ON public.production_catchups TO service_role;
ALTER TABLE public.production_catchups ENABLE ROW LEVEL SECURITY;
CREATE POLICY catchup_read ON public.production_catchups FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id));
CREATE POLICY catchup_staff ON public.production_catchups FOR ALL TO authenticated USING(public.production_staff_access(enrollment_id)) WITH CHECK(public.production_staff_access(enrollment_id) AND sent_by=auth.uid());
CREATE TRIGGER catchup_updated BEFORE UPDATE ON public.production_catchups FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES public.production_enrollments(id) ON DELETE CASCADE, sessions integer NOT NULL CHECK(sessions>0), start_date date NOT NULL DEFAULT current_date, note text NOT NULL DEFAULT '', created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.production_packages TO authenticated; GRANT ALL ON public.production_packages TO service_role;
ALTER TABLE public.production_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY package_read ON public.production_packages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id));
CREATE POLICY package_staff ON public.production_packages FOR INSERT TO authenticated WITH CHECK(public.production_staff_access(enrollment_id) AND created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.level='advanced_plus'));
CREATE TRIGGER package_updated BEFORE UPDATE ON public.production_packages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE POLICY production_media_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='production-media' AND (storage.foldername(name))[2]=auth.uid()::text AND (((storage.foldername(name))[1]='lessons' AND (public.is_admin() OR public.is_production_instructor(auth.uid()))) OR ((storage.foldername(name))[1]='submissions' AND EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.student_id=auth.uid() AND e.active))));
CREATE POLICY production_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='production-media' AND ((storage.foldername(name))[2]=auth.uid()::text OR public.is_admin() OR ((storage.foldername(name))[1]='lessons' AND (public.is_production_instructor(auth.uid()) OR EXISTS(SELECT 1 FROM public.production_modules m, jsonb_array_elements(m.blocks) b WHERE NOT m.is_draft AND b->>'storage_path'=name AND EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.student_id=auth.uid() AND e.active)))) OR ((storage.foldername(name))[1]='submissions' AND EXISTS(SELECT 1 FROM public.production_submissions s WHERE s.storage_path=name AND public.production_staff_access(s.enrollment_id)))));
CREATE POLICY production_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='production-media' AND ((storage.foldername(name))[2]=auth.uid()::text OR public.is_admin()));
CREATE INDEX production_submissions_enrollment ON public.production_submissions(enrollment_id);
CREATE INDEX production_submissions_module ON public.production_submissions(module_id);
CREATE INDEX production_catchups_module ON public.production_catchups(module_id);
